 byte[] fixture(String ext)throws Exception{return new org.springframework.core.io.ClassPathResource("images/synthetic."+ext).getInputStream().readAllBytes();}
 JsonNode upload(String token,byte[] bytes,String filename,int status)throws Exception{String boundary="SyntheticBoundary"+UUID.randomUUID().toString().replace("-","");var out=new java.io.ByteArrayOutputStream();out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\""+filename+"\"\r\nContent-Type: application/octet-stream\r\n\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));out.write(bytes);out.write(("\r\n--"+boundary+"--\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v2/images")).header("Content-Type","multipart/form-data; boundary="+boundary);if(token!=null)builder.header("Authorization","Bearer "+token);var response=HTTP.send(builder.POST(HttpRequest.BodyPublishers.ofByteArray(out.toByteArray())).build(),HttpResponse.BodyHandlers.ofString());assertEquals(status,response.statusCode());return json.readTree(response.body());}
 byte[] content(String token,String id,int status)throws Exception{var response=HTTP.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v2/images/"+id+"/content")).header("Authorization","Bearer "+token).build(),HttpResponse.BodyHandlers.ofByteArray());assertEquals(status,response.statusCode());assertEquals("no-store",response.headers().firstValue("Cache-Control").orElseThrow());return response.body();}
 record Scenario(Account student,Account worker,JsonNode order,String item,String building,String draft,String revision){}
 Scenario scenario(boolean window)throws Exception{
  var u=student();var w=createUser(List.of(roleId("REPAIRER")),"REPAIRER");var asset=asset();long fid=Long.parseLong(asset.id());String item=jdbc.queryForObject("select item_id::text from public.facility_type_repair_item where type_id=(select facility_type_id from public.facility where id=?)",String.class,fid);String building=jdbc.queryForObject("select building_id::text from public.facility where id=?",String.class,fid);
  var now=java.time.OffsetDateTime.now().plusDays(1);call("PUT","/api/v2/workers/"+w.id(),admin,Map.of("version",0,"baseBuildingId",building,"skills",List.of(Map.of("itemId",item,"level",5)),"availability",List.of(Map.of("startAt",now.toString(),"endAt",now.plusDays(7).toString()))),200);
  var body=new HashMap<String,Object>();body.put("itemId",item);body.put("facilityId",asset.id());body.put("description","Synthetic damaged tap");body.put("contactName","Synthetic contact");body.put("phone","00000000000");if(window){body.put("timeMode","WINDOW");body.put("windowStart",now.plusHours(2).toString());body.put("windowEnd",now.plusHours(4).toString());}
  var d=call("POST","/api/v2/drafts",u.token(),body,200);var revision=call("GET","/api/v2/drafts/"+d.path("id").asText(),u.token(),null,200).path("revision").path("id").asText();var o=call("POST","/api/v2/drafts/"+d.path("id").asText()+"/submit",u.token(),Map.of("version",1,"revisionId",revision),200);return new Scenario(u,w,o,item,building,d.path("id").asText(),revision);
 }
 JsonNode op(Scenario s,String action,String token,Map<String,Object>body,int status)throws Exception{var b=new HashMap<>(body);var o=call("GET","/api/v2/orders/"+s.order().path("id").asText(),s.student().token(),null,200);b.put("version",o.path("version").asInt());return call("POST","/api/v2/orders/"+o.path("id").asText()+"/"+action,token,b,status);}
 JsonNode assign(Scenario s)throws Exception{op(s,"review",admin,Map.of("approved",true),200);return op(s,"assign",admin,Map.of("repairerId",Long.toString(s.worker().id())),200);}
 JsonNode appointment(Scenario s,int days)throws Exception{var start=java.time.OffsetDateTime.now().plusDays(days).plusHours(1);return op(s,"appointment",s.worker().token(),Map.of("startAt",start.toString(),"endAt",start.plusHours(1).toString()),200);}
 @Test void normalRealProcessAndEvaluation()throws Exception{var s=scenario(false);String id=s.order().path("id").asText();assertFalse(s.order().path("processInstanceId").asText().isBlank());assertEquals("CONVERTED",jdbc.queryForObject("select state from repair_draft where id=?",String.class,Long.parseLong(s.draft())));assertEquals(1,call("GET","/api/v2/workflow/tasks",admin,null,200).path("total").asInt());var rec=call("GET","/api/v2/orders/"+id+"/recommendations",admin,null,200);assertEquals(1,rec.path("candidates").size());assertTrue(rec.path("adminConfirmationRequired").asBoolean());assign(s);assertEquals("START",appointment(s,1).path("stage").asText());op(s,"start",s.worker().token(),Map.of(),200);op(s,"result",s.worker().token(),Map.of("description","Replaced synthetic seal","materials",List.of(Map.of("name","Seal","quantity",2))),200);var completed=op(s,"acceptance",s.student().token(),Map.of("accepted",true),200);assertEquals("COMPLETED",completed.path("status").asText());assertEquals(1,completed.path("records").size());assertTrue(call("GET","/api/v2/orders/"+id+"/workflow",admin,null,200).path("ended").asBoolean());op(s,"evaluation",s.student().token(),Map.of("stars",5,"comment","Synthetic excellent"),200);op(s,"evaluation",s.student().token(),Map.of("stars",5),409);assertEquals(1,call("GET","/api/v2/statistics",admin,null,200).path("ratings").path("count").asInt());var response=HTTP.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v2/orders/"+id+"/bpmn")).header("Authorization","Bearer "+admin).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,response.statusCode());assertTrue(response.body().contains("subProcess"));assertTrue(call("GET","/api/v2/orders/"+id+"/events",admin,null,200).path("total").asInt()>=8);}
 @Test void rejectionDuplicateAndCrossUserIsolation()throws Exception{var s=scenario(false);String id=s.order().path("id").asText();var other=student();call("GET","/api/v2/orders/"+id,other.token(),null,404);call("GET","/api/v2/orders",other.token(),null,200);call("GET","/api/v2/orders/"+id,null,null,401);op(s,"review",s.student().token(),Map.of("approved",true),403);call("POST","/api/v2/drafts/"+s.draft()+"/submit",s.student().token(),Map.of("version",1,"revisionId",s.revision()),409);var reject=op(s,"review",admin,Map.of("approved",false,"note","Synthetic rejected"),200);assertEquals("REJECTED",reject.path("status").asText());call("POST","/api/v2/orders/"+id+"/review",admin,Map.of("version",0,"approved",true),409);assertTrue(call("GET","/api/v2/orders/"+id+"/workflow",s.student().token(),null,200).path("ended").asBoolean());}
 @Test void adjustmentNegotiationAndTwoReworks()throws Exception{var s=scenario(true);assign(s);assertEquals("APPOINTMENT",appointment(s,2).path("stage").asText());assertEquals("appointmentStudent",call("GET","/api/v2/orders/"+s.order().path("id").asText()+"/workflow",s.student().token(),null,200).path("tasks").get(0).path("node").asText());op(s,"appointment/decision",s.student().token(),Map.of("accepted",false,"reason","Synthetic unavailable"),200);appointment(s,3);op(s,"appointment/decision",s.student().token(),Map.of("accepted",true),200);for(int round=1;round<=3;round++){op(s,"start",s.worker().token(),Map.of(),200);op(s,"result",s.worker().token(),Map.of("description","Synthetic repair round "+round),200);op(s,"acceptance",s.student().token(),round==3?Map.of("accepted",true):Map.of("accepted",false,"reason","Synthetic needs rework"),200);}var o=call("GET","/api/v2/orders/"+s.order().path("id").asText(),s.student().token(),null,200);assertEquals(3,o.path("roundNo").asInt());assertEquals(3,o.path("records").size());assertEquals("COMPLETED",o.path("status").asText());}
 @Test void exceptionResumeAndReassign()throws Exception{var s=scenario(false);assign(s);appointment(s,1);op(s,"start",s.worker().token(),Map.of(),200);op(s,"exception",s.worker().token(),Map.of("type","UNABLE_ENTRY","reason","Synthetic room inaccessible"),200);op(s,"exception/handle",admin,Map.of("decision","RESUME","reason","Synthetic access arranged"),200);op(s,"start",s.worker().token(),Map.of(),200);op(s,"exception",s.worker().token(),Map.of("type","MISSING_MATERIAL","reason","Synthetic no seal"),200);op(s,"exception/handle",admin,Map.of("decision","REASSIGN","reason","Synthetic alternate worker"),200);var w2=createUser(List.of(roleId("REPAIRER")),"REPAIRER");var start=java.time.OffsetDateTime.now().plusDays(1);call("PUT","/api/v2/workers/"+w2.id(),admin,Map.of("version",0,"skills",List.of(Map.of("itemId",s.item(),"level",3)),"availability",List.of(Map.of("startAt",start.toString(),"endAt",start.plusDays(7).toString()))),200);op(s,"assign",admin,Map.of("repairerId",Long.toString(w2.id())),200);call("GET","/api/v2/orders/"+s.order().path("id").asText(),s.worker().token(),null,404);var ns=new Scenario(s.student(),w2,s.order(),s.item(),s.building(),s.draft(),s.revision());appointment(ns,2);op(ns,"start",w2.token(),Map.of(),200);op(ns,"result",w2.token(),Map.of("description","Synthetic replaced"),200);op(ns,"acceptance",s.student().token(),Map.of("accepted",true),200);assertEquals(1,jdbc.queryForObject("select count(*) from v2_appointment where order_id=? and status='CANCELED'",Integer.class,Long.parseLong(s.order().path("id").asText())));}
 @Test void transactionalRollbackAfterRealEngineCommands()throws Exception{var s=scenario(false);assign(s);appointment(s,1);op(s,"start",s.worker().token(),Map.of(),200);long id=Long.parseLong(s.order().path("id").asText());long version=jdbc.queryForObject("select version from v2_order where order_id=?",Long.class,id);doThrow(new IllegalStateException("Injected audit failure")).when(auditTarget).record(any(),eq("CORE_RESULT_SUBMITTED"),anyString(),any(),anyMap());op(s,"result",s.worker().token(),Map.of("description","Synthetic rollback"),500);assertEquals(0,jdbc.queryForObject("select count(*) from repair_record where order_id=?",Integer.class,id));assertEquals(version,jdbc.queryForObject("select version from v2_order where order_id=?",Long.class,id));assertEquals("repairWork",engine.getTaskService().createTaskQuery().processInstanceBusinessKey("repair-order:"+id).singleResult().getTaskDefinitionKey());reset(auditTarget);op(s,"result",s.worker().token(),Map.of("description","Synthetic retry"),200);}
 @Test void scheduleConflictAndConcurrentDuplicateReview()throws Exception{var s=scenario(false);String path="/api/v2/orders/"+s.order().path("id").asText()+"/review";var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->raw("POST",path,admin,Map.of("version",0,"approved",true)).status());var b=pool.submit(()->raw("POST",path,admin,Map.of("version",0,"approved",true)).status());assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}finally{pool.shutdownNow();}op(s,"assign",admin,Map.of("repairerId",Long.toString(s.worker().id())),200);appointment(s,1);call("PUT","/api/v2/workers/"+s.worker().id(),admin,Map.of("version",0,"availability",List.of()),409);call("PUT","/api/v2/workers/me/availability",s.worker().token(),Map.of("version",0,"skills",List.of()),403);call("GET","/api/v2/orders?size=101",admin,null,400);call("GET","/api/v2/statistics",s.student().token(),null,403);}

 @Test void submissionRollbackAndConcurrentConversion()throws Exception{var s=scenario(false);var u=s.student();var d=call("POST","/api/v2/drafts",u.token(),Map.of("itemId",s.item(),"facilityId",jdbc.queryForObject("select facility_id::text from repair_draft_revision where id=?",String.class,Long.parseLong(s.revision())),"description","Synthetic second submission","contactName","Synthetic person","phone","00000000000"),200);String did=d.path("id").asText();String rev=call("GET","/api/v2/drafts/"+did,u.token(),null,200).path("revision").path("id").asText();long before=engine.getRuntimeService().createProcessInstanceQuery().count();int count=jdbc.queryForObject("select count(*) from repair_order",Integer.class);doThrow(new IllegalStateException("Injected post-process failure")).when(auditTarget).record(any(),eq("CORE_SUBMITTED"),anyString(),any(),anyMap());call("POST","/api/v2/drafts/"+did+"/submit",u.token(),Map.of("version",1,"revisionId",rev),500);assertEquals(before,engine.getRuntimeService().createProcessInstanceQuery().count());assertEquals(count,jdbc.queryForObject("select count(*) from repair_order",Integer.class));assertEquals("EDITABLE",jdbc.queryForObject("select state from repair_draft where id=?",String.class,Long.parseLong(did)));reset(auditTarget);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->raw("POST","/api/v2/drafts/"+did+"/submit",u.token(),Map.of("version",1,"revisionId",rev)).status());var b=pool.submit(()->raw("POST","/api/v2/drafts/"+did+"/submit",u.token(),Map.of("version",1,"revisionId",rev)).status());assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}finally{pool.shutdownNow();}assertEquals(count+1,jdbc.queryForObject("select count(*) from repair_order",Integer.class));}
 @Test void scopedFormalImagesDoNotOpenDraftImages()throws Exception{var s=scenario(false);var image=upload(s.student().token(),fixture("png"),"synthetic.png",200);String facility=jdbc.queryForObject("select facility_id::text from repair_draft_revision where id=?",String.class,Long.parseLong(s.revision()));var d=call("POST","/api/v2/drafts",s.student().token(),Map.of("itemId",s.item(),"facilityId",facility,"description","Synthetic image report","contactName","Synthetic contact","phone","00000000000","imageIds",List.of(image.path("id").asText())),200);String did=d.path("id").asText();String rev=call("GET","/api/v2/drafts/"+did,s.student().token(),null,200).path("revision").path("id").asText();var o=call("POST","/api/v2/drafts/"+did+"/submit",s.student().token(),Map.of("version",1,"revisionId",rev),200);String id=o.path("id").asText();var refs=call("GET","/api/v2/orders/"+id+"/images",admin,null,200);assertEquals(1,refs.size());var other=student();String url=refs.get(0).path("contentUrl").asText();for(var pair:List.of(Map.entry(admin,200),Map.entry(s.student().token(),200),Map.entry(other.token(),404),Map.entry(s.worker().token(),404))){var response=HTTP.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+url)).header("Authorization","Bearer "+pair.getKey()).GET().build(),HttpResponse.BodyHandlers.ofByteArray());assertEquals(pair.getValue(),response.statusCode());if(response.statusCode()==200){assertEquals(24,javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(response.body())).getWidth());assertEquals("no-store",response.headers().firstValue("Cache-Control").orElseThrow());}}
 call("GET","/api/v2/images/"+image.path("id").asText(),admin,null,404);call("GET","/api/v2/drafts/"+did,admin,null,404);}
 @Test void submissionRevalidatesSourcesAndNeverAcceptsIncompleteData()throws Exception{var s=scenario(false);var u=s.student();var incomplete=call("POST","/api/v2/drafts",u.token(),Map.of("description","Synthetic incomplete"),200);String did=incomplete.path("id").asText();String rev=call("GET","/api/v2/drafts/"+did,u.token(),null,200).path("revision").path("id").asText();int before=jdbc.queryForObject("select count(*) from repair_order",Integer.class);call("POST","/api/v2/drafts/"+did+"/submit",u.token(),Map.of("version",1,"revisionId",rev),409);var asset=asset();String item=jdbc.queryForObject("select item_id::text from facility_type_repair_item where type_id=(select facility_type_id from facility where id=?)",String.class,Long.parseLong(asset.id()));var d=call("POST","/api/v2/drafts",u.token(),Map.of("itemId",item,"facilityId",asset.id(),"description","Synthetic fresh draft","contactName","Synthetic contact","phone","00000000000"),200);did=d.path("id").asText();rev=call("GET","/api/v2/drafts/"+did,u.token(),null,200).path("revision").path("id").asText();jdbc.update("update repair_item set enabled=false where id=?",Long.parseLong(item));call("POST","/api/v2/drafts/"+did+"/submit",u.token(),Map.of("version",1,"revisionId",rev),409);assertEquals(before,jdbc.queryForObject("select count(*) from repair_order",Integer.class));}
 @Test void confirmedBookingConflictAndRecommendationFiltering()throws Exception{var s=scenario(false);assign(s);var begin=java.time.OffsetDateTime.now().plusDays(2);op(s,"appointment",s.worker().token(),Map.of("startAt",begin.toString(),"endAt",begin.plusHours(1).toString()),200);String facility=jdbc.queryForObject("select facility_id::text from repair_draft_revision where id=?",String.class,Long.parseLong(s.revision()));var u=s.student();var d=call("POST","/api/v2/drafts",u.token(),Map.of("itemId",s.item(),"facilityId",facility,"description","Synthetic overlapping request","contactName","Synthetic contact","phone","00000000000","timeMode","WINDOW","windowStart",begin.toString(),"windowEnd",begin.plusMinutes(30).toString()),200);String rev=call("GET","/api/v2/drafts/"+d.path("id").asText(),u.token(),null,200).path("revision").path("id").asText();var o=call("POST","/api/v2/drafts/"+d.path("id").asText()+"/submit",u.token(),Map.of("version",1,"revisionId",rev),200);String id=o.path("id").asText();var r=call("GET","/api/v2/orders/"+id+"/recommendations",admin,null,200);assertEquals(0,r.path("candidates").size());assertEquals("TIME_CONFLICT",r.path("excluded").get(0).path("reason").asText());var second=new Scenario(u,s.worker(),o,s.item(),s.building(),d.path("id").asText(),rev);assign(second);op(second,"appointment",s.worker().token(),Map.of("startAt",begin.plusMinutes(10).toString(),"endAt",begin.plusHours(1).toString()),409);var other=createUser(List.of(roleId("REPAIRER")),"REPAIRER");call("POST","/api/v2/orders/"+id+"/start",other.token(),Map.of("version",2),404);}

